/**
 * A styled native table, the main data display in ListPage (`design/components/table.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  agentMember,
  cell,
  classes,
  derived,
  elementRef,
  getters,
  mountEffect,
  pressTableSort,
  provideOwner,
  tableSort,
  tableSortColumns,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/table.module.css'
import type { TableCellProps } from './TableCell'
import type { TableHeaderProps } from './TableHeader'
import type { TableRowProps } from './TableRow'

export type CellProps = TableCellProps

export type HeaderProps = TableHeaderProps

export type RowProps = TableRowProps

export type SortDirection = 'asc' | 'desc'

/** A styled native table, the main data display in ListPage: the inputs it takes, by the React member's prop names. */
export interface TableProps {
  /**
   * Names the **table** with a real `<caption>`, its first child. `label` names the *scroll
   * region*, which exists only while the columns overflow, so a table that fits has no name.
   * That is fine for a page's main table, but a dashboard's chart twin tables would be announced
   * as "table, table, table". Announced but not drawn unless `captionVisible`, because most
   * tables already have their name on screen: a page title, or the chart they are the twin of.
   */
  caption?: string
  /**
   * Draws the caption above the table as well as announcing it, for a table whose name is not
   * already beside it. Not left to composition as Heading's caption is, because a `Text` above
   * the table would not be connected to it, and `<caption>` is the element for a table's name.
   */
  captionVisible?: boolean
  /**
   * The table is a **grid**: one tab stop, arrow keys between cells, and rows that may carry
   * `aria-selected`. Only for a component that owns every cell, in practice DataTable. A
   * hand-composed table is a document of prose and links, browsed with the reader's own keys,
   * and taking the arrow keys for a focus ring would only cost them.
   */
  grid?: boolean
  /**
   * Names the scroll region for keyboard users, usually the page's title.
   */
  label?: string
  /**
   * Rows can be selected in bulk. Only meaningful inside a grid, where it tells a screen reader
   * whether "selected" means one of many or the only one.
   */
  multiselectable?: boolean
  stickyHeader?: boolean
}

/** What Table hands its compound parts. */
export interface TableOwner {
  readonly grid: Exclude<TableProps['grid'], undefined>
}

/** A styled native table, the main data display in ListPage. */
@Component({
  selector: 'pm-table',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS, provideOwner('Table')],
  imports: [Ref, SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- wrapper -->
<div
[attr.class]="e1()"
[attr.data-sticky-header]="e2()"
[attr.data-overflowing]="e3()"
[attr.tabindex]="e4()"
[attr.role]="e5()"
[attr.aria-label]="e6()"
data-member="table"
[pmRef]="wrapper"
><!-- table -->
<table
[attr.class]="e7()"
[attr.role]="e8()"
[attr.aria-multiselectable]="e9()"
(focusin)="h1($event)"
(focusout)="h2($event)"
(keydown)="h3($event)"
[pmRef]="table"
>@if (e10()) {<!-- caption -->
<caption
[attr.class]="e11()"
>{{ e12() }}</caption>}
<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></table></div>`,
})
export class Table {
  /**
   * Names the **table** with a real `<caption>`, its first child. `label` names the *scroll
   * region*, which exists only while the columns overflow, so a table that fits has no name.
   * That is fine for a page's main table, but a dashboard's chart twin tables would be announced
   * as "table, table, table". Announced but not drawn unless `captionVisible`, because most
   * tables already have their name on screen: a page title, or the chart they are the twin of.
   */
  readonly caption = input<TableProps['caption']>(undefined)
  /**
   * Draws the caption above the table as well as announcing it, for a table whose name is not
   * already beside it. Not left to composition as Heading's caption is, because a `Text` above
   * the table would not be connected to it, and `<caption>` is the element for a table's name.
   */
  readonly captionVisible = input<
    Exclude<TableProps['captionVisible'], undefined>,
    TableProps['captionVisible']
  >(false, {
    transform: (value: TableProps['captionVisible']) => (value === undefined ? false : value),
  })
  /**
   * The table is a **grid**: one tab stop, arrow keys between cells, and rows that may carry
   * `aria-selected`. Only for a component that owns every cell, in practice DataTable. A
   * hand-composed table is a document of prose and links, browsed with the reader's own keys,
   * and taking the arrow keys for a focus ring would only cost them.
   */
  readonly grid = input<Exclude<TableProps['grid'], undefined>, TableProps['grid']>(false, {
    transform: (value: TableProps['grid']) => (value === undefined ? false : value),
  })
  /**
   * Names the scroll region for keyboard users, usually the page's title.
   */
  readonly label = input<TableProps['label']>(undefined)
  /**
   * Rows can be selected in bulk. Only meaningful inside a grid, where it tells a screen reader
   * whether "selected" means one of many or the only one.
   */
  readonly multiselectable = input<
    Exclude<TableProps['multiselectable'], undefined>,
    TableProps['multiselectable']
  >(false, {
    transform: (value: TableProps['multiselectable']) => (value === undefined ? false : value),
  })
  readonly stickyHeader = input<
    Exclude<TableProps['stickyHeader'], undefined>,
    TableProps['stickyHeader']
  >(false, {
    transform: (value: TableProps['stickyHeader']) => (value === undefined ? false : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: {
      caption: () => this.caption(),
      captionVisible: () => this.captionVisible(),
      grid: () => this.grid(),
      label: () => this.label(),
      multiselectable: () => this.multiselectable(),
      stickyHeader: () => this.stickyHeader(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly overflowing = cell(() => false)
  protected readonly at = cell(() => ({ row: 0, column: 0, detail: false }))
  protected readonly placed = cell(() => false)
  protected readonly holds = cell(() => false)
  protected readonly table = elementRef<HTMLElement>()
  protected readonly wrapper = elementRef<HTMLElement>()
  protected readonly stopIn = derived(() => (cell: HTMLTableCellElement): HTMLElement => {
    for (const node of Array.from(
      cell.querySelectorAll<HTMLElement>('button, a[href], input, select, textarea'),
    )) {
      if (node.hasAttribute('disabled') || node.getAttribute('aria-hidden') === 'true') continue
      return node
    }
    return cell
  })
  protected readonly gridRows = derived(
    () =>
      (element: HTMLTableElement): HTMLTableRowElement[] =>
        Array.from(element.rows).filter((row) => !row.hasAttribute('data-detail')),
  )
  protected readonly detailUnder = derived(
    () =>
      (row: HTMLTableRowElement | undefined): HTMLTableCellElement | null => {
        const next = row?.nextElementSibling
        return next instanceof HTMLTableRowElement && next.hasAttribute('data-detail')
          ? (next.cells[0] ?? null)
          : null
      },
  )
  protected readonly gridCellOf = derived(
    () =>
      (element: HTMLTableElement, target: EventTarget | null): HTMLTableCellElement | null => {
        let cell =
          target instanceof HTMLElement ? target.closest<HTMLTableCellElement>('th, td') : null
        while (cell !== null && cell.closest('table') !== element) {
          cell = cell.parentElement?.closest<HTMLTableCellElement>('th, td') ?? null
        }
        if (cell === null || cell.parentElement === null) return null
        return cell.parentElement.hasAttribute('data-detail') && cell !== target ? null : cell
      },
  )
  protected readonly positionOf = derived(
    () =>
      (
        element: HTMLTableElement,
        cell: HTMLTableCellElement,
        column: number,
      ): { row: number; column: number; detail: boolean } => {
        const row = cell.parentElement as HTMLTableRowElement
        const rows = this.gridRows.value(element)
        return row.hasAttribute('data-detail')
          ? {
              row: rows.indexOf(row.previousElementSibling as HTMLTableRowElement),
              column,
              detail: true,
            }
          : { row: rows.indexOf(row), column: cell.cellIndex, detail: false }
      },
  )
  protected readonly clampCell = derived(
    () =>
      (
        element: HTMLTableElement,
        to: { row: number; column: number; detail: boolean },
      ): { row: number; column: number; detail: boolean } | null => {
        const rows = this.gridRows.value(element)
        const row = Math.min(Math.max(to.row, 0), rows.length - 1)
        const cells = rows[row]?.cells
        if (cells === undefined || cells.length === 0) return null
        return {
          row,
          column: Math.min(Math.max(to.column, 0), cells.length - 1),
          detail: to.detail && row === to.row && this.detailUnder.value(rows[row]) !== null,
        }
      },
  )
  protected readonly startOf = derived(
    () =>
      (element: HTMLTableElement): { row: number; column: number; detail: boolean } => {
        const cells = Array.from(this.gridRows.value(element)[0]?.cells ?? [])
        const column = cells.findIndex((cell) => cell.querySelector('[data-undrawn]') === null)
        return { row: 0, column: Math.max(column, 0), detail: false }
      },
  )
  protected readonly whereIn = derived(
    () =>
      (element: HTMLTableElement): { row: number; column: number; detail: boolean } =>
        this.placed.value ? this.at.value : this.startOf.value(element),
  )
  protected readonly stopAt = derived(
    () =>
      (
        element: HTMLTableElement,
        to: { row: number; column: number; detail: boolean },
      ): HTMLElement | null => {
        const row = this.gridRows.value(element)[to.row]
        if (to.detail) return this.detailUnder.value(row)
        const cell = row?.cells[to.column]
        return cell === undefined ? null : this.stopIn.value(cell)
      },
  )
  protected readonly rove = derived(
    () => (element: HTMLTableElement, to: { row: number; column: number; detail: boolean }) => {
      this.at.value = to
      for (const [index, row] of this.gridRows.value(element).entries()) {
        for (const cell of Array.from(row.cells)) {
          const stop = this.stopIn.value(cell)
          const wanted = !to.detail && index === to.row && cell.cellIndex === to.column ? '0' : '-1'
          if (stop !== cell && cell.getAttribute('tabindex') !== '-1')
            cell.setAttribute('tabindex', '-1')
          if (stop.getAttribute('tabindex') !== wanted) stop.setAttribute('tabindex', wanted)
        }
        const under = this.detailUnder.value(row)
        const held = to.detail && index === to.row ? '0' : '-1'
        if (under !== null && under.getAttribute('tabindex') !== held)
          under.setAttribute('tabindex', held)
      }
    },
  )
  protected readonly focusIn = derived(() => (event: FocusEvent) => {
    const element = this.table.value as HTMLTableElement | null
    if (element === null) return
    if (!this.holds.value) this.holds.value = true
    const cell = this.gridCellOf.value(element, event.target)
    if (cell === null) return
    const to = this.clampCell.value(
      element,
      this.positionOf.value(element, cell, this.whereIn.value(element).column),
    )
    if (to === null) return
    this.placed.value = true
    this.rove.value(element, to)
  })
  protected readonly focusOut = derived(() => (event: FocusEvent) => {
    const element = this.table.value as HTMLTableElement | null
    const left = event.target
    queueMicrotask(() => {
      if (
        element !== null &&
        left instanceof Node &&
        left.isConnected &&
        !element.contains(document.activeElement)
      )
        this.holds.value = false
    })
  })
  protected readonly keyDown = derived(() => (event: KeyboardEvent) => {
    const element = this.table.value as HTMLTableElement | null
    const target = event.target instanceof HTMLElement ? event.target : null
    if (
      element === null ||
      target === null ||
      target.closest(
        'input:not([type="checkbox"]):not([type="radio"]), textarea, [contenteditable]',
      ) !== null
    )
      return
    const cell = this.gridCellOf.value(element, target)
    if (cell === null) return
    const rows = this.gridRows.value(element)
    const here = this.positionOf.value(element, cell, this.whereIn.value(element).column)
    const forward = getComputedStyle(element).direction === 'rtl' ? -1 : 1
    const far = event.ctrlKey || event.metaKey
    const last = Number.MAX_SAFE_INTEGER
    let next: { row: number; column: number; detail: boolean } | null
    if (here.detail) {
      switch (event.key) {
        case 'ArrowDown':
          next = here.row + 1 < rows.length ? { ...here, row: here.row + 1, detail: false } : null
          break
        case 'ArrowUp':
          next = { ...here, detail: false }
          break
        case 'ArrowRight':
        case 'ArrowLeft':
          next = null
          break
        case 'Home':
          next = far ? { row: 0, column: 0, detail: false } : null
          break
        case 'End':
          next = far ? { row: last, column: last, detail: false } : null
          break
        default:
          return
      }
    } else {
      switch (event.key) {
        case 'ArrowRight':
          next = { ...here, column: here.column + forward }
          break
        case 'ArrowLeft':
          next = { ...here, column: here.column - forward }
          break
        case 'ArrowDown':
          next =
            this.detailUnder.value(rows[here.row]) !== null
              ? { ...here, detail: true }
              : { ...here, row: here.row + 1 }
          break
        case 'ArrowUp':
          next =
            this.detailUnder.value(rows[here.row - 1]) !== null
              ? { ...here, row: here.row - 1, detail: true }
              : { ...here, row: here.row - 1 }
          break
        case 'Home':
          next = far ? { row: 0, column: 0, detail: false } : { ...here, column: 0 }
          break
        case 'End':
          next = far ? { row: last, column: last, detail: false } : { ...here, column: last }
          break
        default:
          return
      }
    }
    event.preventDefault()
    const to = next === null ? null : this.clampCell.value(element, next)
    if (to === null) return
    this.placed.value = true
    this.rove.value(element, to)
    this.stopAt.value(element, to)?.focus()
  })
  protected readonly reclamp = derived(() => () => {
    const element = this.table.value as HTMLTableElement | null
    if (element === null || !this.$p.grid) return
    const to = this.clampCell.value(element, this.whereIn.value(element))
    if (to === null) return
    this.rove.value(element, to)
    const fell = document.activeElement === null || document.activeElement === document.body
    if (this.holds.value && fell) this.stopAt.value(element, to)?.focus()
  })
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined
  private release3: (() => void) | undefined

  constructor() {
    this.$.owner = getters<TableOwner>({ grid: () => this.$p.grid })
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
    inject(DestroyRef).onDestroy(() => this.release2?.())
    watchEffect(
      () => this.$p.grid,
      () => this.effect2(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return styles.wrapper
  }

  protected e2() {
    return this.$p.stickyHeader ? '' : undefined
  }

  protected e3() {
    return this.overflowing.value ? '' : undefined
  }

  protected e4() {
    return this.overflowing.value && !this.$p.grid ? '0' : undefined
  }

  protected e5() {
    return this.overflowing.value && this.$p.label !== undefined ? 'region' : undefined
  }

  protected e6() {
    return this.overflowing.value ? this.$p.label : undefined
  }

  protected e7() {
    return styles.table
  }

  protected e8() {
    return this.$p.grid ? 'grid' : undefined
  }

  protected e9() {
    return this.$p.grid && this.$p.multiselectable ? 'true' : undefined
  }

  protected h1($event: FocusEvent): void {
    if (this.$p.grid) {
      this.focusIn.value($event)
    }
  }

  protected h2($event: FocusEvent): void {
    if (this.$p.grid) {
      this.focusOut.value($event)
    }
  }

  protected h3($event: KeyboardEvent): void {
    if (this.$p.grid) {
      this.keyDown.value($event)
    }
  }

  protected e10() {
    return this.$p.caption !== undefined
  }

  protected e11() {
    if (!(this.$p.caption !== undefined)) return undefined as never
    return classes(
      this.$p.captionVisible ? styles.caption : undefined,
      !this.$p.captionVisible ? styles.captionHidden : undefined,
    )
  }

  protected e12() {
    if (!(this.$p.caption !== undefined)) return undefined as never
    return this.$p.caption
  }

  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.overflowing.value =
        this.wrapper.value !== null &&
        this.wrapper.value.scrollWidth > this.wrapper.value.clientWidth
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.wrapper.value, this.wrapper.value?.firstElementChild])
      if (element) resize?.observe(element)
    this.release1 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.release2?.()
    const run = () => {
      this.reclamp.value()
    }
    const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
    for (const element of [this.table.value])
      if (element)
        mutation?.observe(element, {
          childList: true,
          characterData: true,
          subtree: true,
          attributeFilter: ['disabled'],
        })
    this.release2 = () => {
      mutation?.disconnect()
    }
    run()
  }

  private effect3(): void {
    this.release3?.()
    const ran =
      this.wrapper.value?.parentElement?.closest('[data-member]')?.getAttribute('data-member') ===
      'data-table'
        ? () => {}
        : agentMember({
            member: 'Table',
            element: () => this.wrapper.value,
            state: () => ({
              'sort-key': tableSort(this.table.value).key,
              'sort-direction': tableSort(this.table.value).direction,
              columns: tableSortColumns(this.table.value),
            }),
            actions: {
              sort: { argument: 'id', run: (value) => pressTableSort(this.table.value, value) },
            },
          })
    this.release3 = () => {
      ran()
    }
  }
}
